"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Button Group: generated by UIX from the design system. Same variants and sizes as the Figma component.

const buttonGroupVariants = cva(
  "inline-flex items-stretch overflow-hidden [&>*]:inline-flex [&>*]:cursor-pointer [&>*]:items-center [&>*]:justify-center [&>*]:whitespace-nowrap [&>*]:transition-colors [&>*]:disabled:pointer-events-none [&>*]:disabled:text-fg-disabled [&>*]:focus-visible:outline-none [&>*]:focus-visible:ring-2 [&>*]:focus-visible:ring-inset [&>*]:focus-visible:ring-line-focus rounded-md",
  {
    variants: {
      variant: {
        outline: "border border-line-default [&>*+*]:border-l [&>*+*]:border-line-default [&>*]:text-fg-secondary [&>*]:hover:bg-subtle [&>*]:aria-pressed:bg-subtle [&>*]:aria-pressed:text-fg-primary",
        primary: "skin-solid bg-brand [&>*+*]:border-l [&>*+*]:border-fg-on-brand/30 [&>*]:text-fg-on-brand [&>*]:hover:bg-brand-hover [&>*]:aria-pressed:bg-brand-pressed",
        ghost: "skin-quiet [&>*]:text-fg-secondary [&>*]:hover:bg-subtle [&>*]:aria-pressed:bg-subtle [&>*]:aria-pressed:text-fg-primary",
      },
      size: {
        sm: "h-8 [&>*]:px-3 [&>*]:gap-1-5 [&>*]:text-label-small [&_svg]:size-4",
        md: "h-10 [&>*]:px-4 [&>*]:gap-2 [&>*]:text-label-medium [&_svg]:size-5",
        lg: "h-12 [&>*]:px-5 [&>*]:gap-2 [&>*]:text-label-large [&_svg]:size-5",
      },
    },
    defaultVariants: {
      variant: "outline",
      size: "md",
    },
  },
);

export interface ButtonGroupProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof buttonGroupVariants> {}

const ButtonGroup = React.forwardRef<HTMLDivElement, ButtonGroupProps>(
  ({ className, variant, size, ...props }, ref) => (
    <div data-slot="button-group" data-kind="control" ref={ref} role="group" className={cn(buttonGroupVariants({ variant, size }), className)} {...props} />
  ),
);
ButtonGroup.displayName = "ButtonGroup";

export interface ButtonGroupItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Marks the segment as the active one. */
  pressed?: boolean;
}

const ButtonGroupItem = React.forwardRef<HTMLButtonElement, ButtonGroupItemProps>(
  ({ pressed, type = "button", ...props }, ref) => <button ref={ref} type={type} aria-pressed={pressed} {...props} />,
);
ButtonGroupItem.displayName = "ButtonGroupItem";

export { ButtonGroup, ButtonGroupItem, buttonGroupVariants };
